import type { GradeKey, Step } from "../../lib/rang-ara/content";

export type BookRawLevel = {
  id: string;
  poet: string;
  /** `beyt` شمارهٔ بیت در درسنامه است؛ در درسِ نثر شمارهٔ بند. */
  book: { grade: GradeKey; lesson: number; title: string; beyt: number };
  lines: string[];
  meaning: string;
  steps: Step[];
};

/* ═══════════════════════════════════════════════════════════════════════════
   «رنگ‌آرا» — پیشنهادِ بیت‌های کتابِ درسی برای seed (`npm run db:seed-rang-ara`).
   ═══════════════════════════════════════════════════════════════════════════

   ⚠️ متنِ مصراع‌ها و «معنی» عیناً از درسنامهٔ سروا (`lib/doroos/content`)
   کپی شده و هر آرایه از بخشِ رایگانِ «قلمرو ادبی» همان بیت آمده است — نه از
   `devices`: آن نقشه پشتِ سروا پلاس است و نباید به bundleِ کلاینت برسد.

   ⚠️ این فایل هرگز به bundleِ سایت نمی‌رسد؛ بازی بیت‌هایش را فقط از
   دیتابیس می‌خواند و seed این‌ها را *پیش‌نویس* وارد می‌کند تا مدیر بازبینی و
   منتشر کند. تستِ `rang-ara.test.ts` هر بیت را با درسنامه مقایسه می‌کند؛ اگر
   متنِ درس عوض شود و این فایل نه، تست می‌شکند.

   شناسهٔ واژه‌ها («1-3») روی `hemistich.split(/s+/)` است، همان قراردادِ
   درسنامه.

   ── درسِ نثر ─────────────────────────────────────────────────────────────
   از بندِ نثر (و شعرِ نو و هر بندِ بیش از دو سطر) هرگز کلِ بند نمی‌آید: کارتِ بازی برای دو مصراع ساخته شده و
   بندِ بلند یا ریز می‌شود یا کارت را می‌شکند. پس هر «مصراع» یک برشِ کوتاه
   از همان بند است، به همان ترتیب و عیناً با همان متن (تست این را می‌سنجد)،
   و «معنی» فقط همان برش را معنا می‌کند. اگر یک بند چند برش داشته باشد، شناسهٔ
   برش‌های بعدی پسوندِ «b»، «c»، … می‌گیرند (`davazdahom-01-6b`).

   بیت‌هایی که درسِ نثر از شاعرِ دیگری نقل کرده و درسنامه سراینده‌شان را
   نمی‌گوید، `poet` خالی دارند؛ نامِ شاعر حدس زده نمی‌شود.

   ⚠️ برش باید هر چیزی را که جواب به آن تکیه دارد در خودش داشته باشد؛ بازیکن
   فقط همین دو سطر را می‌بیند. «آب را تا باغستان و مزرعه مشایعت می‌کنند»
   بدونِ «درختان» تشخیص نیست، و «از این بوستان که بودی» بدونِ «بحر مکاشفت»
   استعاره نیست. اگر مشبّه، فاعلِ تشخیص یا مرجعِ استعاره پیش از برش آمده،
   برش از همان‌جا شروع می‌شود (دو سطر می‌توانند از دو جای همان بند باشند).

   ── اضافهٔ استعاری ─────────────────────────────────────────────────────────
   ترکیبی مثل «سینهٔ کویر»، «دستِ زمان»، «دلِ خاک» (عضو یا ویژگیِ انسانی +
   غیرانسان) اضافهٔ استعاری است و گامش «استعاره» است، نه «تشخیص». «تشخیص»
   برای خودِ غیرانسانی است که کار، صفت یا خطابِ انسانی گرفته («درختان …
   مشایعت می‌کنند»، «ای دماوند»). */

